  describe("Ambitious (Transformers One Sourcebook, Influence Perk, p.12)", () => {
    const AMBITIOUS_ID = "Compendium.essence20.transformers_one_sourcebook.Item.eLoPulLITRqroJu5";

    function makeAmbitiousActor({ hasPerk = true, usedThisEncounter = false } = {}) {
      return {
        ...mockActor,
        items: hasPerk ? [{ type: 'perk', flags: { core: { sourceId: AMBITIOUS_ID } } }] : [],
        getRollData: jest.fn(() => ({ skills: { athletics: { modifier: '0', shift: 'd20' } } })),
        getFlag: jest.fn((scope, key) => (
          key == 'ambitiousUsedThisEncounter' && usedThisEncounter ? { combatId: 'combat1' } : undefined
        )),
        setFlag: jest.fn(),
      };
    }

    let originalCombat;
    beforeEach(() => {
      originalCombat = game.combat;
      game.combat = { id: 'combat1' };
    });
    afterEach(() => {
      game.combat = originalCombat;
    });

    test("offered on any roll with the Perk, not yet used this scene", async () => {
      const rollDialog = createMockRollDialog();
      rollDialog.getSkillRollOptions.mockReturnValue({
        canCritD2: false, edge: false, snag: false, shiftUp: 0, shiftDown: 0, timesToRoll: 1,
      });
      dice._rollSkillHelper = jest.fn();

      await dice.rollSkill(dataset, makeAmbitiousActor(), null);

      expect(rollDialog.getSkillRollOptions.mock.calls[0][0].ambitiousAvailable).toBe(true);
    });

    test("not offered without the Perk, or once already used this scene", async () => {
      const rollDialog = createMockRollDialog();
      rollDialog.getSkillRollOptions.mockReturnValue({
        canCritD2: false, edge: false, snag: false, shiftUp: 0, shiftDown: 0, timesToRoll: 1,
      });
      dice._rollSkillHelper = jest.fn();

      await dice.rollSkill(dataset, makeAmbitiousActor({ hasPerk: false }), null);
      expect(rollDialog.getSkillRollOptions.mock.calls[0][0].ambitiousAvailable).toBe(false);

      await dice.rollSkill(dataset, makeAmbitiousActor({ usedThisEncounter: true }), null);
      expect(rollDialog.getSkillRollOptions.mock.calls[1][0].ambitiousAvailable).toBe(false);
    });

    test("applying it zeroes Snag and shiftDown, and marks the scene used", async () => {
      const rollDialog = createMockRollDialog();
      const resolvedOptions = {
        canCritD2: false, edge: false, snag: true, shiftUp: 0, shiftDown: 2, timesToRoll: 1,
        applyAmbitious: true,
      };
      rollDialog.getSkillRollOptions.mockReturnValue(resolvedOptions);
      dice._rollSkillHelper = jest.fn();
      const actor = makeAmbitiousActor();

      await dice.rollSkill(dataset, actor, null);

      expect(resolvedOptions.snag).toBe(false);
      expect(resolvedOptions.shiftDown).toBe(0);
      expect(actor.setFlag).toHaveBeenCalledWith('essence20', 'ambitiousUsedThisEncounter', expect.any(Object));
    });
  });

