  describe("Unseen Strike (Across the Stars, Phantom Ranger, 9th level, p.61)", () => {
    const UNSEEN_STRIKE_ID = "Compendium.essence20.across_the_stars.Item.EYdpn9PL4iNrQPkh";

    function makeActor({ hasPerk = true, suiteActive = true, usedThisTurn = false } = {}) {
      const items = hasPerk ? [{ type: 'perk', flags: { core: { sourceId: UNSEEN_STRIKE_ID } } }] : [];
      return {
        ...mockActor,
        items,
        getFlag: jest.fn((scope, key) => {
          if (key == 'phantomSuiteActive') {
            return suiteActive;
          }
          if (key == 'unseenStrikeUsedThisTurn') {
            return usedThisTurn ? { combatId: 'combat1', round: 1, turn: 0 } : undefined;
          }
          return undefined;
        }),
        setFlag: jest.fn(),
        getRollData: jest.fn(() => ({ skills: { might: { modifier: '0', shift: 'd20' } } })),
      };
    }

    function makeTargetActor(overrides = {}) {
      return {
        name: 'Target',
        uuid: 'Actor.target1',
        system: { defenses: { evasion: { total: 11 } }, immunities: {}, size: 'common' },
        statuses: new Set(),
        items: [],
        getFlag: jest.fn(),
        setFlag: jest.fn(),
        unsetFlag: jest.fn(),
        ...overrides,
      };
    }

    function makeTargetsSet(targetActor) {
      const token = { actor: targetActor, center: { x: 0, y: 0 } };
      const set = new Set([token]);
      set.first = () => token;

      return set;
    }

    const meleeEvasionWeaponEffect = {
      type: 'weaponEffect',
      flags: {},
      system: {
        classification: { skill: 'might', style: 'melee' }, damageType: 'blunt', damageValue: 1,
        defenseType: 'evasion',
      },
    };

    let originalTargets;
    beforeEach(() => {
      originalTargets = game.user.targets;
      game.combat = { id: 'combat1', round: 1, turn: 0 };
    });
    afterEach(() => {
      game.user.targets = originalTargets;
      game.combat = null;
    });

    test("halves (rounding up) the target's Evasion Defense on the first attack this turn", async () => {
      const rollDialog = createMockRollDialog();
      rollDialog.getSkillRollOptions.mockReturnValue({
        canCritD2: false, edge: false, snag: false, shiftUp: 0, shiftDown: 0, timesToRoll: 1, defenseType: 'evasion',
      });
      dice._rollSkillHelper = jest.fn();
      game.user.targets = makeTargetsSet(makeTargetActor());

      await dice.rollSkill({ ...dataset, skill: 'might', essence: 'strength' }, makeActor(), meleeEvasionWeaponEffect);

      expect(dice._rollSkillHelper.mock.calls[0][4].entries[0].difficulty).toBe(6); // ceil(11 / 2)
    });

    test("marks the turn used even before the roll resolves", async () => {
      const rollDialog = createMockRollDialog();
      rollDialog.getSkillRollOptions.mockReturnValue({
        canCritD2: false, edge: false, snag: false, shiftUp: 0, shiftDown: 0, timesToRoll: 1, defenseType: 'evasion',
      });
      dice._rollSkillHelper = jest.fn();
      const actor = makeActor();
      game.user.targets = makeTargetsSet(makeTargetActor());

      await dice.rollSkill({ ...dataset, skill: 'might', essence: 'strength' }, actor, meleeEvasionWeaponEffect);

      expect(actor.setFlag).toHaveBeenCalledWith(
        'essence20', 'unseenStrikeUsedThisTurn', expect.objectContaining({ combatId: 'combat1', round: 1, turn: 0 }),
      );
    });

    test("doesn't apply on a second attack the same turn", async () => {
      const rollDialog = createMockRollDialog();
      rollDialog.getSkillRollOptions.mockReturnValue({
        canCritD2: false, edge: false, snag: false, shiftUp: 0, shiftDown: 0, timesToRoll: 1, defenseType: 'evasion',
      });
      dice._rollSkillHelper = jest.fn();
      game.user.targets = makeTargetsSet(makeTargetActor());

      await dice.rollSkill(
        { ...dataset, skill: 'might', essence: 'strength' }, makeActor({ usedThisTurn: true }), meleeEvasionWeaponEffect,
      );

      expect(dice._rollSkillHelper.mock.calls[0][4].entries[0].difficulty).toBe(11);
    });

    test("doesn't apply without the Perk, while Phantom Suite is inactive, or against a non-Evasion Defense", async () => {
      const rollDialog = createMockRollDialog();
      dice._rollSkillHelper = jest.fn();

      rollDialog.getSkillRollOptions.mockReturnValue({
        canCritD2: false, edge: false, snag: false, shiftUp: 0, shiftDown: 0, timesToRoll: 1, defenseType: 'evasion',
      });
      game.user.targets = makeTargetsSet(makeTargetActor());
      await dice.rollSkill(
        { ...dataset, skill: 'might', essence: 'strength' }, makeActor({ hasPerk: false }), meleeEvasionWeaponEffect,
      );
      expect(dice._rollSkillHelper.mock.calls[0][4].entries[0].difficulty).toBe(11);

      game.user.targets = makeTargetsSet(makeTargetActor());
      await dice.rollSkill(
        { ...dataset, skill: 'might', essence: 'strength' }, makeActor({ suiteActive: false }), meleeEvasionWeaponEffect,
      );
      expect(dice._rollSkillHelper.mock.calls[1][4].entries[0].difficulty).toBe(11);

      rollDialog.getSkillRollOptions.mockReturnValue({
        canCritD2: false, edge: false, snag: false, shiftUp: 0, shiftDown: 0, timesToRoll: 1, defenseType: 'toughness',
      });
      const toughnessWeaponEffect = {
        ...meleeEvasionWeaponEffect, system: { ...meleeEvasionWeaponEffect.system, defenseType: 'toughness' },
      };
      game.user.targets = makeTargetsSet(makeTargetActor({ system: { defenses: { toughness: { total: 11 } }, immunities: {}, size: 'common' } }));
      await dice.rollSkill({ ...dataset, skill: 'might', essence: 'strength' }, makeActor(), toughnessWeaponEffect);
      expect(dice._rollSkillHelper.mock.calls[2][4].entries[0].difficulty).toBe(11);
    });
  });

