  describe("Observer (Through the Shattered Grid, Guardian of Eltar, 10th level, p.72) - reciprocal Tech-scan Snag", () => {
    const OBSERVER_ID = "Compendium.essence20.through_the_shattered_grid.Item.PTkqeQ8D4x9cstlZ";

    function makeAttackerActor() {
      return {
        ...mockActor,
        items: [],
        getRollData: jest.fn(() => ({ skills: { technology: { modifier: '0', shift: 'd20' } } })),
      };
    }

    function makeTargetActor({ hasPerk = true, disguised = true } = {}) {
      return {
        name: 'Target',
        system: { defenses: { willpower: { total: 10 } }, immunities: {}, size: 'common' },
        statuses: new Set(),
        items: hasPerk ? [{ type: 'perk', flags: { core: { sourceId: OBSERVER_ID } } }] : [],
        getFlag: jest.fn((scope, key) => (key == 'observerDisguiseActive' ? disguised : undefined)),
      };
    }

    function makeTargetsSet(targetActor) {
      const token = { actor: targetActor, center: {} };
      const set = new Set([token]);
      set.first = () => token;
      return set;
    }

    let originalTargets;
    beforeEach(() => {
      originalTargets = game.user.targets;
    });
    afterEach(() => {
      game.user.targets = originalTargets;
    });

    test("Snags a Technology roll against a disguised holder", async () => {
      const rollDialog = createMockRollDialog();
      rollDialog.getSkillRollOptions.mockReturnValue({
        canCritD2: false, edge: false, snag: false, shiftUp: 0, shiftDown: 0, timesToRoll: 1,
      });
      dice._rollSkillHelper = jest.fn();
      game.user.targets = makeTargetsSet(makeTargetActor());

      await dice.rollSkill({ ...dataset, skill: 'technology', essence: 'smarts' }, makeAttackerActor(), null);

      expect(rollDialog.getSkillRollOptions.mock.calls[0][1].snag).toBe(true);
    });

    test("doesn't apply without the Perk, while not disguised, or on a non-Technology roll", async () => {
      const rollDialog = createMockRollDialog();
      rollDialog.getSkillRollOptions.mockReturnValue({
        canCritD2: false, edge: false, snag: false, shiftUp: 0, shiftDown: 0, timesToRoll: 1,
      });
      dice._rollSkillHelper = jest.fn();

      game.user.targets = makeTargetsSet(makeTargetActor({ hasPerk: false }));
      await dice.rollSkill({ ...dataset, skill: 'technology', essence: 'smarts' }, makeAttackerActor(), null);
      expect(rollDialog.getSkillRollOptions.mock.calls[0][1].snag).toBe(false);

      game.user.targets = makeTargetsSet(makeTargetActor({ disguised: false }));
      await dice.rollSkill({ ...dataset, skill: 'technology', essence: 'smarts' }, makeAttackerActor(), null);
      expect(rollDialog.getSkillRollOptions.mock.calls[1][1].snag).toBe(false);
    });
  });

