        return {
          ...mockActor,
          items,
          getRollData: jest.fn(() => ({ skills: { targeting: { modifier: '0', shift: 'd8' } } })),
          getFlag: jest.fn((scope, key) => (key == 'pendingCalculatedAttack' && pending ? { active: true } : undefined)),
          unsetFlag: jest.fn(),
        };
