    describe("Martial Weapon Master (Factions in Action Vol. 2, General Perk, p.32)", () => {
      const MARTIAL_WEAPON_MASTER_ID = "Compendium.essence20.intercontinental_adventures.Item.HZiYXNZOeFExJa4K";

      function makeWeaponActor({ perkIds = [], weaponTraits = [] } = {}) {
        const weapon = { id: 'weapon1', system: { traits: weaponTraits } };
        const items = perkIds.map(perkId => ({ type: 'perk', flags: { core: { sourceId: perkId } } }));
        items.get = jest.fn((id) => (id == 'weapon1' ? weapon : null));

        return {
          ...mockActor,
          items,
          system: { ...mockActor.system, essenceShifts: { any: { shiftUp: 0, shiftDown: 0 }, strength: { shiftUp: 0, shiftDown: 0 } } },
          getRollData: jest.fn(() => ({ skills: { might: { modifier: '0', shift: 'd20' } } })),
        };
      }

      function makeWeaponEffect(weaponTraits) {
        return {
          type: 'weaponEffect',
          flags: { essence20: { parentId: 'weapon1' } },
          system: { classification: { skill: 'might', style: 'melee' }, damageType: 'blunt', damageValue: 1 },
          _traitsForFixture: weaponTraits,
        };
      }

      test("upshifts an Attack with a Martial Arts weapon", async () => {
        const rollDialog = createMockRollDialog();
        rollDialog.getSkillRollOptions.mockReturnValue({
          canCritD2: false, edge: false, snag: false, shiftUp: 0, shiftDown: 0, timesToRoll: 1,
        });
        dice._rollSkillHelper = jest.fn();
        const actor = makeWeaponActor({ perkIds: [MARTIAL_WEAPON_MASTER_ID], weaponTraits: ['martialArts'] });

        await dice.rollSkill({ ...dataset, skill: 'might', essence: 'strength' }, actor, makeWeaponEffect(['martialArts']));

        expect(rollDialog.getSkillRollOptions.mock.calls[0][0].shiftUp).toBe(1);
        expect(rollDialog.getSkillRollOptions.mock.calls[0][0].shiftDown).toBe(0);
      });

      test("downshifts an Attack with a non-Martial-Arts weapon", async () => {
        const rollDialog = createMockRollDialog();
        rollDialog.getSkillRollOptions.mockReturnValue({
          canCritD2: false, edge: false, snag: false, shiftUp: 0, shiftDown: 0, timesToRoll: 1,
        });
        dice._rollSkillHelper = jest.fn();
        const actor = makeWeaponActor({ perkIds: [MARTIAL_WEAPON_MASTER_ID], weaponTraits: ['ballistic'] });

        await dice.rollSkill({ ...dataset, skill: 'might', essence: 'strength' }, actor, makeWeaponEffect(['ballistic']));

        expect(rollDialog.getSkillRollOptions.mock.calls[0][0].shiftUp).toBe(0);
        expect(rollDialog.getSkillRollOptions.mock.calls[0][0].shiftDown).toBe(1);
      });

      test("doesn't apply without the Perk, or on an unarmed attack (no parent weapon)", async () => {
        const rollDialog = createMockRollDialog();
        rollDialog.getSkillRollOptions.mockReturnValue({
          canCritD2: false, edge: false, snag: false, shiftUp: 0, shiftDown: 0, timesToRoll: 1,
        });
        dice._rollSkillHelper = jest.fn();

        const noPerkActor = makeWeaponActor({ weaponTraits: ['ballistic'] });
        await dice.rollSkill({ ...dataset, skill: 'might', essence: 'strength' }, noPerkActor, makeWeaponEffect(['ballistic']));
        expect(rollDialog.getSkillRollOptions.mock.calls[0][0].shiftUp).toBe(0);
        expect(rollDialog.getSkillRollOptions.mock.calls[0][0].shiftDown).toBe(0);

        const unarmedActor = makeWeaponActor({ perkIds: [MARTIAL_WEAPON_MASTER_ID] });
        const unarmedEffect = { type: 'weaponEffect', flags: {}, system: { classification: { skill: 'finesse', style: 'melee' }, damageType: 'blunt', damageValue: 1 } };
        await dice.rollSkill({ ...dataset, skill: 'might', essence: 'strength' }, unarmedActor, unarmedEffect);
        expect(rollDialog.getSkillRollOptions.mock.calls[1][0].shiftUp).toBe(0);
        expect(rollDialog.getSkillRollOptions.mock.calls[1][0].shiftDown).toBe(0);
      });
    });

