    describe("Low Tech Priorities (A Jump Through Time, Low Tech Origin Benefit, p.28)", () => {
      const LOW_TECH_PRIORITIES_ID = "Compendium.essence20.jump_through_time.Item.khD9UfuqUQ4rWSUP";

      beforeEach(() => {
        game.combat = { id: 'combat1', round: 1, turn: 0 };
      });

      afterEach(() => {
        game.combat = null;
      });

      function makeActor({ choices = [], usedThisTurn = false } = {}) {
        const items = choices.map(choice => ({
          type: 'perk', flags: { core: { sourceId: LOW_TECH_PRIORITIES_ID } }, system: { choice },
        }));
        const flags = usedThisTurn
          ? { lowTechPrioritiesUsedThisTurn: { combatId: 'combat1', round: 1, turn: 0 } }
          : {};
        return {
          ...mockActor,
          items,
          getFlag: jest.fn((scope, key) => flags[key]),
          setFlag: jest.fn(async (scope, key, value) => {
            flags[key] = value;
          }),
          getRollData: jest.fn(() => ({ skills: { culture: { modifier: '0', shift: 'd8' } } })),
        };
      }

      test("cancels 1 point of downshift on either chosen skill", async () => {
        const rollDialog = createMockRollDialog();
        rollDialog.getSkillRollOptions.mockReturnValue({
          canCritD2: false, edge: false, snag: false, shiftUp: 0, shiftDown: 3, timesToRoll: 1,
        });
        dice._rollSkillHelper = jest.fn();
        const actor = makeActor({ choices: ['culture', 'survival'] });

        await dice.rollSkill({ ...dataset, skill: 'culture', essence: 'smarts', shift: 'd8', shiftDown: 1 }, actor, null);

        expect(actor.setFlag).toHaveBeenCalledWith(
          'essence20', 'lowTechPrioritiesUsedThisTurn', expect.anything(),
        );
      });

      test("doesn't apply to an unchosen skill, without the Perk, or once already used this turn", async () => {
        const rollDialog = createMockRollDialog();
        rollDialog.getSkillRollOptions.mockReturnValue({
          canCritD2: false, edge: false, snag: false, shiftUp: 0, shiftDown: 3, timesToRoll: 1,
        });
        dice._rollSkillHelper = jest.fn();

        const wrongSkillActor = makeActor({ choices: ['survival'] });
        await dice.rollSkill({ ...dataset, skill: 'culture', essence: 'smarts', shift: 'd8' }, wrongSkillActor, null);
        expect(wrongSkillActor.setFlag).not.toHaveBeenCalled();

        const noPerkActor = makeActor();
        await dice.rollSkill({ ...dataset, skill: 'culture', essence: 'smarts', shift: 'd8' }, noPerkActor, null);
        expect(noPerkActor.setFlag).not.toHaveBeenCalled();

        const alreadyUsedActor = makeActor({ choices: ['culture'], usedThisTurn: true });
        await dice.rollSkill({ ...dataset, skill: 'culture', essence: 'smarts', shift: 'd8' }, alreadyUsedActor, null);
        expect(alreadyUsedActor.setFlag).not.toHaveBeenCalledWith(
          'essence20', 'lowTechPrioritiesUsedThisTurn', expect.anything(),
        );
      });
    });

