    describe("Angry Influence (Cobra Codex, p.26)", () => {
      const ANGRY_ID = "Compendium.essence20.cobra_codex.Item.fHmLPZ3K8AGgzANp";

      function makeAngryActor({ perkIds = [], usedThisEncounter = false } = {}) {
        const actor = makeActor({ perkIds });
        actor.getFlag = jest.fn((scope, key) => (
          key == 'angryUsedThisEncounter' && usedThisEncounter ? { combatId: 'combat1' } : undefined
        ));
        actor.setFlag = jest.fn();
        return actor;
      }

      beforeEach(() => {
        game.combat = { id: 'combat1' };
      });

      afterEach(() => {
        game.combat = null;
      });

      test("is available once per encounter on a Strength Skill Test with the Perk", async () => {
        const rollDialog = createMockRollDialog();
        rollDialog.getSkillRollOptions.mockReturnValue({
          canCritD2: false, edge: false, snag: false, shiftUp: 0, shiftDown: 0, timesToRoll: 1,
        });
        dice._rollSkillHelper = jest.fn();
        const actor = makeAngryActor({ perkIds: [ANGRY_ID] });

        await dice.rollSkill({ ...dataset, skill: 'brawn', essence: 'strength' }, actor, null);

        expect(rollDialog.getSkillRollOptions.mock.calls[0][0].angryAvailable).toBe(true);
      });

      test("isn't available without the Perk, on a non-Strength skill, or once already used this encounter", async () => {
        const rollDialog = createMockRollDialog();
        rollDialog.getSkillRollOptions.mockReturnValue({
          canCritD2: false, edge: false, snag: false, shiftUp: 0, shiftDown: 0, timesToRoll: 1,
        });
        dice._rollSkillHelper = jest.fn();

        await dice.rollSkill({ ...dataset, skill: 'brawn', essence: 'strength' }, makeAngryActor(), null);
        expect(rollDialog.getSkillRollOptions.mock.calls[0][0].angryAvailable).toBe(false);

        const actor = makeAngryActor({ perkIds: [ANGRY_ID] });
        await dice.rollSkill({ ...dataset, skill: 'deception', essence: 'social' }, actor, null);
        expect(rollDialog.getSkillRollOptions.mock.calls[1][0].angryAvailable).toBe(false);

        const usedActor = makeAngryActor({ perkIds: [ANGRY_ID], usedThisEncounter: true });
        await dice.rollSkill({ ...dataset, skill: 'brawn', essence: 'strength' }, usedActor, null);
        expect(rollDialog.getSkillRollOptions.mock.calls[2][0].angryAvailable).toBe(false);
      });

      test("checking the box grants Edge and marks it used this encounter", async () => {
        const rollDialog = createMockRollDialog();
        rollDialog.getSkillRollOptions.mockReturnValue({
          canCritD2: false, edge: false, snag: false, shiftUp: 0, shiftDown: 0, timesToRoll: 1, applyAngry: true,
        });
        dice._rollSkillHelper = jest.fn();
        const actor = makeAngryActor({ perkIds: [ANGRY_ID] });

        await dice.rollSkill({ ...dataset, skill: 'brawn', essence: 'strength' }, actor, null);

        expect(actor.setFlag).toHaveBeenCalledWith('essence20', 'angryUsedThisEncounter', { combatId: 'combat1' });
      });
    });

