    describe("Roaring Engine (Factions in Action Vol. 2, General Perk, p.64)", () => {
      const ROARING_ENGINE_ID = "Compendium.essence20.intercontinental_adventures.Item.zzEmLhFcExVXhT5g";

      function makeDriverActor({ hasPerk = true, isDriving = true } = {}) {
        return {
          ...mockActor,
          type: 'playerCharacter',
          uuid: 'Actor.driver1',
          items: hasPerk ? [{ type: 'perk', flags: { core: { sourceId: ROARING_ENGINE_ID } } }] : [],
          getRollData: jest.fn(() => ({
            skills: { intimidation: { modifier: '0', shift: 'd6' }, driving: { modifier: '0', shift: 'd10' } },
          })),
        };
      }

      let originalActors;
      beforeEach(() => {
        originalActors = global.game.actors;
      });
      afterEach(() => {
        global.game.actors = originalActors;
      });

      function stubPilotedVehicle(driverActor, { isDriving = true } = {}) {
        global.game.actors = isDriving
          ? [{ type: 'vehicle', system: { actors: { crew1: { vehicleRole: 'driver', uuid: driverActor.uuid } } } }]
          : [];
      }

      test("roaringEngineAvailable is true only on Intimidation, while driving, with the Perk", async () => {
        const rollDialog = createMockRollDialog();
        rollDialog.getSkillRollOptions.mockReturnValue({
          canCritD2: false, edge: false, snag: false, shiftUp: 0, shiftDown: 0, timesToRoll: 1,
        });
        dice._rollSkillHelper = jest.fn();

        const actor = makeDriverActor();
        stubPilotedVehicle(actor);
        await dice.rollSkill({ ...dataset, skill: 'intimidation', essence: 'social' }, actor, null);
        expect(rollDialog.getSkillRollOptions.mock.calls[0][0].roaringEngineAvailable).toBe(true);

        const notDrivingActor = makeDriverActor();
        stubPilotedVehicle(notDrivingActor, { isDriving: false });
        await dice.rollSkill({ ...dataset, skill: 'intimidation', essence: 'social' }, notDrivingActor, null);
        expect(rollDialog.getSkillRollOptions.mock.calls[1][0].roaringEngineAvailable).toBe(false);

        const noPerkActor = makeDriverActor({ hasPerk: false });
        stubPilotedVehicle(noPerkActor);
        await dice.rollSkill({ ...dataset, skill: 'intimidation', essence: 'social' }, noPerkActor, null);
        expect(rollDialog.getSkillRollOptions.mock.calls[2][0].roaringEngineAvailable).toBe(false);
      });

      test("substitutes the Driving die as a shiftUp when checked", async () => {
        const rollDialog = createMockRollDialog();
        const returnedOptions = {
          canCritD2: false, edge: false, snag: false, shiftUp: 0, shiftDown: 0, timesToRoll: 1, applyRoaringEngine: true,
        };
        rollDialog.getSkillRollOptions.mockReturnValue(returnedOptions);
        dice._rollSkillHelper = jest.fn();
        const actor = makeDriverActor();
        stubPilotedVehicle(actor);

        await dice.rollSkill({ ...dataset, skill: 'intimidation', essence: 'social', shift: 'd6' }, actor, null);

        expect(returnedOptions.shiftUp).toBe(2); // d6 -> d10
      });
    });

