    describe("Technically Correct (Quartermaster's Guide to Gear, Tech Officer Focus, Officer, 6th level, p.22)", () => {
      const TECHNICALLY_CORRECT_ID = "Compendium.essence20.quartermasters_guide_to_gear.Item.HU9eLTJr0aFxiqnd";

      function makeActor({ hasPerk = true, usedThisEncounter = false } = {}) {
        return {
          ...mockActor,
          items: hasPerk ? [{ type: 'perk', flags: { core: { sourceId: TECHNICALLY_CORRECT_ID } } }] : [],
          getRollData: jest.fn(() => ({
            skills: { intimidation: { modifier: '0', shift: 'd6' }, technology: { modifier: '0', shift: 'd10' } },
          })),
          getFlag: jest.fn((scope, key) => (
            key == 'technicallyCorrectUsedThisEncounter' && usedThisEncounter ? { combatId: 'combat1' } : undefined
          )),
          setFlag: jest.fn(),
        };
      }

      let originalCombat;
      beforeEach(() => {
        originalCombat = game.combat;
        game.combat = { id: 'combat1' };
      });
      afterEach(() => {
        game.combat = originalCombat;
      });

      test("technicallyCorrectAvailable is true on a non-Technology roll, with the Perk, not yet used this scene", async () => {
        const rollDialog = createMockRollDialog();
        rollDialog.getSkillRollOptions.mockReturnValue({
          canCritD2: false, edge: false, snag: false, shiftUp: 0, shiftDown: 0, timesToRoll: 1,
        });
        dice._rollSkillHelper = jest.fn();

        await dice.rollSkill({ ...dataset, skill: 'intimidation', essence: 'social' }, makeActor(), null);
        expect(rollDialog.getSkillRollOptions.mock.calls[0][0].technicallyCorrectAvailable).toBe(true);

        await dice.rollSkill({ ...dataset, skill: 'technology', essence: 'smarts' }, makeActor(), null);
        expect(rollDialog.getSkillRollOptions.mock.calls[1][0].technicallyCorrectAvailable).toBe(false);

        await dice.rollSkill({ ...dataset, skill: 'intimidation', essence: 'social' }, makeActor({ hasPerk: false }), null);
        expect(rollDialog.getSkillRollOptions.mock.calls[2][0].technicallyCorrectAvailable).toBe(false);

        await dice.rollSkill(
          { ...dataset, skill: 'intimidation', essence: 'social' }, makeActor({ usedThisEncounter: true }), null,
        );
        expect(rollDialog.getSkillRollOptions.mock.calls[3][0].technicallyCorrectAvailable).toBe(false);
      });

      test("substitutes the Technology die as a shiftUp when checked, and marks the scene used", async () => {
        const rollDialog = createMockRollDialog();
        const returnedOptions = {
          canCritD2: false, edge: false, snag: false, shiftUp: 0, shiftDown: 0, timesToRoll: 1,
          applyTechnicallyCorrect: true,
        };
        rollDialog.getSkillRollOptions.mockReturnValue(returnedOptions);
        dice._rollSkillHelper = jest.fn();
        const actor = makeActor();

        await dice.rollSkill({ ...dataset, skill: 'intimidation', essence: 'social', shift: 'd6' }, actor, null);

        expect(returnedOptions.shiftUp).toBe(2); // d6 -> d10
        expect(actor.setFlag).toHaveBeenCalledWith(
          'essence20', 'technicallyCorrectUsedThisEncounter', expect.any(Object),
        );
      });
    });

