    describe("Saber-Toothed (Factions in Action Vol 1: Ferocious Fighters, General Perk, p.37)", () => {
      const SABER_TOOTHED_ID = "Compendium.essence20.ferocious_fighters.Item.RVGlDHOKipqZ1e7i";

      function makeUnarmedWeaponEffect() {
        return {
          type: 'weaponEffect', flags: {},
          system: { classification: { skill: 'might', style: 'melee' }, damageType: 'blunt', damageValue: 1 },
        };
      }

      function makeTargetsSet() {
        const targetActor = {
          name: 'Target', uuid: 'Actor.target1',
          system: { defenses: { toughness: { total: 10 } }, immunities: {}, size: 'common' },
          statuses: new Set(), items: [],
        };
        const token = { actor: targetActor, center: { x: 0, y: 0 } };
        const set = new Set([token]);
        set.first = () => token;
        return set;
      }

      let originalTargets;
      beforeEach(() => {
        originalTargets = game.user.targets;
        game.user.targets = makeTargetsSet();
      });
      afterEach(() => {
        game.user.targets = originalTargets;
      });

      test("suffers ↓1 and deals Sharp instead of Blunt when checked on an unarmed attack", async () => {
        const rollDialog = createMockRollDialog();
        const returnedOptions = {
          canCritD2: false, edge: false, snag: false, shiftUp: 0, shiftDown: 0, timesToRoll: 1, applySaberToothed: true,
          defenseType: 'toughness',
        };
        rollDialog.getSkillRollOptions.mockReturnValue(returnedOptions);
        dice._rollSkillHelper = jest.fn();
        const actor = makeActor({ perkIds: [SABER_TOOTHED_ID] });
        actor.items.get = jest.fn(() => null);
        actor.getRollData = jest.fn(() => ({ skills: { might: { modifier: '0', shift: 'd8' } } }));

        await dice.rollSkill({ ...dataset, skill: 'might', essence: 'strength', shift: 'd8' }, actor, makeUnarmedWeaponEffect());

        expect(returnedOptions.shiftDown).toBe(1);
        expect(dice._rollSkillHelper.mock.calls[0][4].damageType).toBe('sharp');
      });

      test("doesn't apply without the Perk, unchecked, or with a real weapon", async () => {
        const rollDialog = createMockRollDialog();
        rollDialog.getSkillRollOptions.mockReturnValue({
          canCritD2: false, edge: false, snag: false, shiftUp: 0, shiftDown: 0, timesToRoll: 1, applySaberToothed: true,
          defenseType: 'toughness',
        });
        dice._rollSkillHelper = jest.fn();

        const noPerkActor = makeActor();
        noPerkActor.items.get = jest.fn(() => null);
        noPerkActor.getRollData = jest.fn(() => ({ skills: { might: { modifier: '0', shift: 'd8' } } }));
        await dice.rollSkill(
          { ...dataset, skill: 'might', essence: 'strength', shift: 'd8' }, noPerkActor, makeUnarmedWeaponEffect(),
        );
        expect(dice._rollSkillHelper.mock.calls[0][4].damageType).toBe('blunt');

        const armedActor = makeActor({ perkIds: [SABER_TOOTHED_ID] });
        armedActor.items.get = jest.fn(() => ({ system: { itemAndUpgradeTraits: [] } }));
        armedActor.getRollData = jest.fn(() => ({ skills: { might: { modifier: '0', shift: 'd8' } } }));
        await dice.rollSkill(
          { ...dataset, skill: 'might', essence: 'strength', shift: 'd8' },
          armedActor,
          { ...makeUnarmedWeaponEffect(), flags: { essence20: { parentId: 'weapon1' } } },
        );
        expect(dice._rollSkillHelper.mock.calls[1][4].damageType).toBe('blunt');
      });
    });

