/* _applySmashDamage */
describe("_applySmashDamage (Enigma of Combination, Pugilist Focus, Warrior, 20th level)", () => {
  const SMASH_ID = "Compendium.essence20.enigma_of_combination.Item.psPOXCaZFo7yiRzD";

  function makeActor({ perkIds = [], size = 'large' } = {}) {
    const items = perkIds.map(perkId => ({ type: 'perk', flags: { core: { sourceId: perkId } } }));
    return { items, system: { size } };
  }

  const unarmedContext = { isUnarmedAttack: true };
  const armedContext = { isUnarmedAttack: false };

  function makeResult({ targetUuid = 'Actor.target1', damageValue = 1, success = true } = {}) {
    return { targetUuid, damageValue, success };
  }

  beforeEach(() => {
    fromUuid.mockReset();
  });

  test("adds 1 damage per Size Class larger and knocks a successfully-hit smaller target Prone", async () => {
    const targetActor = { system: { size: 'small' }, toggleStatusEffect: jest.fn() };
    fromUuid.mockResolvedValue(targetActor);
    const results = [makeResult({ damageValue: 1 })];

    await dice._applySmashDamage(makeActor({ perkIds: [SMASH_ID], size: 'large' }), results, unarmedContext);

    expect(results[0].damageValue).toBe(3); // large(2) - small(0) = 2 Size Classes -> +2
    expect(targetActor.toggleStatusEffect).toHaveBeenCalledWith('prone', { active: true });
  });

  test("applies Prone even without a damage value to add to", async () => {
    const targetActor = { system: { size: 'small' }, toggleStatusEffect: jest.fn() };
    fromUuid.mockResolvedValue(targetActor);
    const results = [makeResult({ damageValue: null })];

    await dice._applySmashDamage(makeActor({ perkIds: [SMASH_ID], size: 'large' }), results, unarmedContext);

    expect(results[0].damageValue).toBeNull();
    expect(targetActor.toggleStatusEffect).toHaveBeenCalledWith('prone', { active: true });
  });

  test("doesn't apply against a target that isn't at least one Size Class smaller", async () => {
    const sameSizeTarget = { system: { size: 'large' }, toggleStatusEffect: jest.fn() };
    fromUuid.mockResolvedValue(sameSizeTarget);
    const results = [makeResult({ damageValue: 1 })];

    await dice._applySmashDamage(makeActor({ perkIds: [SMASH_ID], size: 'large' }), results, unarmedContext);

    expect(results[0].damageValue).toBe(1);
    expect(sameSizeTarget.toggleStatusEffect).not.toHaveBeenCalled();
  });

  test("doesn't apply without the Perk", async () => {
    const targetActor = { system: { size: 'small' }, toggleStatusEffect: jest.fn() };
    fromUuid.mockResolvedValue(targetActor);
    const results = [makeResult({ damageValue: 1 })];

    await dice._applySmashDamage(makeActor({ size: 'large' }), results, unarmedContext);

    expect(results[0].damageValue).toBe(1);
    expect(fromUuid).not.toHaveBeenCalled();
  });

  test("doesn't apply to an attack that isn't weaponless", async () => {
    const targetActor = { system: { size: 'small' }, toggleStatusEffect: jest.fn() };
    fromUuid.mockResolvedValue(targetActor);
    const results = [makeResult({ damageValue: 1 })];

    await dice._applySmashDamage(makeActor({ perkIds: [SMASH_ID], size: 'large' }), results, armedContext);

    expect(results[0].damageValue).toBe(1);
    expect(fromUuid).not.toHaveBeenCalled();
  });

  test("doesn't apply on a miss", async () => {
    const results = [makeResult({ success: false })];

    await dice._applySmashDamage(makeActor({ perkIds: [SMASH_ID], size: 'large' }), results, unarmedContext);

    expect(fromUuid).not.toHaveBeenCalled();
  });
});

