  describe("Dogfighter (Across the Stars, General Perk, p.68)", () => {
    const DOGFIGHTER_ID = "Compendium.essence20.across_the_stars.Item.twl2N01FD8XKO0s1";

    function makePilotActor({ hasPerk = true } = {}) {
      return {
        uuid: 'Actor.pilot1',
        type: 'playerCharacter',
        items: hasPerk ? [{ type: 'perk', flags: { core: { sourceId: DOGFIGHTER_ID } } }] : [],
        statuses: new Set(),
        getFlag: jest.fn(),
      };
    }

    function makeAerialVehicleActor({ size = 'huge', aerial = 20, crew = { crew1: { vehicleRole: 'driver', uuid: 'Actor.pilot1' } } } = {}) {
      return { type: 'vehicle', system: { size, movement: { aerial: { base: aerial } }, actors: crew } };
    }

    function makeTargetVehicle({ aerial = 20 } = {}) {
      return { type: 'vehicle', uuid: 'Actor.target1', system: { movement: { aerial: { base: aerial } } } };
    }

    afterEach(() => {
      global.game.actors = undefined;
    });

    test("grants an Edge on Driving/Targeting against another aerial vehicle while piloting a qualifying aerial vehicle", () => {
      global.game.actors = [makeAerialVehicleActor()];
      game.user.targets.first.mockReturnValue({ actor: makeTargetVehicle() });
      const actor = makePilotActor();

      expect(dice._getAutomaticCombatModifiers(actor, null, null, 'driving'))
        .toEqual({ ...defaultModifiers, edge: true, sources: [
    {
      "edge": true,
      "id": "dogfighter",
      "label": "Dogfighter",
      "shiftDown": 0,
      "shiftUp": 0,
      "snag": false,
    },
  ] });

      expect(dice._getAutomaticCombatModifiers(actor, null, null, 'targeting'))
        .toEqual({ ...defaultModifiers, edge: true, sources: [
    {
      "edge": true,
      "id": "dogfighter",
      "label": "Dogfighter",
      "shiftDown": 0,
      "shiftUp": 0,
      "snag": false,
    },
  ] });
    });

    test("doesn't apply against a non-aerial vehicle target", () => {
      global.game.actors = [makeAerialVehicleActor()];
      game.user.targets.first.mockReturnValue({ actor: makeTargetVehicle({ aerial: 0 }) });

      expect(dice._getAutomaticCombatModifiers(makePilotActor(), null, null, 'driving')).toEqual(defaultModifiers);
    });

    test("doesn't apply against a non-vehicle target", () => {
      global.game.actors = [makeAerialVehicleActor()];
      game.user.targets.first.mockReturnValue({ actor: { type: 'playerCharacter', uuid: 'Actor.target1', system: {} } });

      expect(dice._getAutomaticCombatModifiers(makePilotActor(), null, null, 'driving')).toEqual(defaultModifiers);
    });

    test("doesn't apply while piloting a vehicle too large to qualify (bigger than Extended II)", () => {
      global.game.actors = [makeAerialVehicleActor({ size: 'towering' })];
      game.user.targets.first.mockReturnValue({ actor: makeTargetVehicle() });

      expect(dice._getAutomaticCombatModifiers(makePilotActor(), null, null, 'driving')).toEqual(defaultModifiers);
    });

    test("doesn't apply while piloting a non-aerial vehicle", () => {
      global.game.actors = [makeAerialVehicleActor({ aerial: 0 })];
      game.user.targets.first.mockReturnValue({ actor: makeTargetVehicle() });

      expect(dice._getAutomaticCombatModifiers(makePilotActor(), null, null, 'driving')).toEqual(defaultModifiers);
    });

    test("doesn't apply without the Perk, or when not piloting at all", () => {
      global.game.actors = [makeAerialVehicleActor()];
      game.user.targets.first.mockReturnValue({ actor: makeTargetVehicle() });

      expect(dice._getAutomaticCombatModifiers(makePilotActor({ hasPerk: false }), null, null, 'driving'))
        .toEqual(defaultModifiers);

      global.game.actors = [];
      expect(dice._getAutomaticCombatModifiers(makePilotActor(), null, null, 'driving')).toEqual(defaultModifiers);
    });
  });

