  describe("Grappling's own Size downshift (GI Joe CRB, Chapter 9: Combat, p.200) / Jacket Wrestler (Factions in Action Vol. 2, Arashikage General Perk, p.32)", () => {
    const JACKET_WRESTLER_ID = "Compendium.essence20.intercontinental_adventures.Item.59masYwRaPC1AuhQ";
    const grappleWeaponEffect = {
      type: 'weaponEffect',
      system: { classification: { style: 'melee' }, defenseType: 'evasion', damageType: 'grapple' },
    };

    test("downshifts a Grapple attack against a larger target, capped at 2", () => {
      // common(1) vs long(3), diff 2 - right at the cap.
      game.user.targets.first.mockReturnValue({ actor: makeActor('long') });
      const actor = makeActor('common');

      const result = dice._getAutomaticCombatModifiers(actor, grappleWeaponEffect);
      expect(result.shiftDown).toBe(2);
      expect(result.sources.some(s => s.id == 'grappleSize')).toBe(true);
    });

    test("caps the downshift at 2 even when the target is more than 2 Size Classes larger", () => {
      game.user.targets.first.mockReturnValue({ actor: makeActor('titanic') }); // small(0) -> titanic(10)
      const actor = makeActor('small');

      expect(dice._getAutomaticCombatModifiers(actor, grappleWeaponEffect).shiftDown).toBe(2);
    });

    test("doesn't downshift against a same-size or smaller target, or a non-Grapple attack", () => {
      game.user.targets.first.mockReturnValue({ actor: makeActor('common') });
      expect(dice._getAutomaticCombatModifiers(makeActor('common'), grappleWeaponEffect).shiftDown).toBe(0);

      game.user.targets.first.mockReturnValue({ actor: makeActor('small') });
      expect(dice._getAutomaticCombatModifiers(makeActor('common'), grappleWeaponEffect).shiftDown).toBe(0);

      game.user.targets.first.mockReturnValue({ actor: makeActor('long') });
      expect(dice._getAutomaticCombatModifiers(makeActor('common'), meleeWeaponEffect).shiftDown).toBe(0);
    });

    test("Jacket Wrestler suppresses the downshift entirely", () => {
      game.user.targets.first.mockReturnValue({ actor: makeActor('long') });
      const actor = makeActor('common', [], { perkIds: [JACKET_WRESTLER_ID] });

      const result = dice._getAutomaticCombatModifiers(actor, grappleWeaponEffect);
      expect(result.shiftDown).toBe(0);
      expect(result.sources.some(s => s.id == 'grappleSize')).toBe(false);
    });
  });

  describe("Oorah! (Sgt Slaughter Sourcebook, Slaughter's Marauders Faction Perk, p.15) / Catch Off Guard (Marauder Focus, Vanguard, 1st level, p.15) - Surprised-target checks", () => {
    const OORAH_ID = "Compendium.essence20.sgt_slaughter_sourcebook.Item.7CuDik9Vtpou9iDJ";
    const CATCH_OFF_GUARD_ID = "Compendium.essence20.sgt_slaughter_sourcebook.Item.qplsg3JI3kmUCtU9";

    function makeCombat({ turn, combatantIndex }) {
      const combatant = { actor: { uuid: 'target-uuid' } };
      const turns = [];
      turns[combatantIndex] = combatant;

      return {
        turn,
        turns,
        combatants: { find: jest.fn(finder => (finder(combatant) ? combatant : undefined)) },
      };
    }

    afterEach(() => {
      game.combat = null;
    });

    test("Oorah! reports a +1 oorahDamageBonus against a Surprised (hasn't-acted-yet) target", () => {
      const target = makeActor('common');
      target.uuid = 'target-uuid';
      game.user.targets.first.mockReturnValue({ actor: target });
      game.combat = makeCombat({ turn: 0, combatantIndex: 2 });
      const actor = makeActor('common', [], { perkIds: [OORAH_ID] });

      const result = dice._getAutomaticCombatModifiers(actor, meleeWeaponEffect);
      expect(result.oorahDamageBonus).toBe(1);
    });

    test("Oorah! doesn't apply against a target who already acted, or without the Perk", () => {
      const target = makeActor('common');
      target.uuid = 'target-uuid';
      game.user.targets.first.mockReturnValue({ actor: target });

      game.combat = makeCombat({ turn: 2, combatantIndex: 0 });
      expect(dice._getAutomaticCombatModifiers(makeActor('common', [], { perkIds: [OORAH_ID] }), meleeWeaponEffect)
        .oorahDamageBonus).toBe(0);

      game.combat = makeCombat({ turn: 0, combatantIndex: 2 });
      expect(dice._getAutomaticCombatModifiers(makeActor('common'), meleeWeaponEffect).oorahDamageBonus).toBe(0);
    });

    test("Catch Off Guard flags isCatchOffGuardAttempt against a Surprised target", () => {
      const target = makeActor('common');
      target.uuid = 'target-uuid';
      game.user.targets.first.mockReturnValue({ actor: target });
      game.combat = makeCombat({ turn: 0, combatantIndex: 2 });
      const actor = makeActor('common', [], { perkIds: [CATCH_OFF_GUARD_ID] });

      expect(dice._getAutomaticCombatModifiers(actor, meleeWeaponEffect).isCatchOffGuardAttempt).toBe(true);
    });

    test("Catch Off Guard doesn't flag against a target who already acted, or without the Perk", () => {
      const target = makeActor('common');
      target.uuid = 'target-uuid';
      game.user.targets.first.mockReturnValue({ actor: target });

      game.combat = makeCombat({ turn: 2, combatantIndex: 0 });
      expect(dice._getAutomaticCombatModifiers(makeActor('common', [], { perkIds: [CATCH_OFF_GUARD_ID] }), meleeWeaponEffect)
        .isCatchOffGuardAttempt).toBe(false);

      game.combat = makeCombat({ turn: 0, combatantIndex: 2 });
      expect(dice._getAutomaticCombatModifiers(makeActor('common'), meleeWeaponEffect).isCatchOffGuardAttempt).toBe(false);
    });

    test("neither check crashes without an active combat at all", () => {
      game.combat = null;
      const target = makeActor('common');
      game.user.targets.first.mockReturnValue({ actor: target });
      const actor = makeActor('common', [], { perkIds: [OORAH_ID, CATCH_OFF_GUARD_ID] });

      const result = dice._getAutomaticCombatModifiers(actor, meleeWeaponEffect);
      expect(result.oorahDamageBonus).toBe(0);
      expect(result.isCatchOffGuardAttempt).toBe(false);
    });
  });

