  describe("Tech Specs (Quartermaster's Guide to Gear, Tech Officer Focus, Officer, 10th level, p.22)", () => {
    function makeAttackerActor({ disposition = 1 } = {}) {
      return {
        ...makeActor('common'),
        id: 'roller1',
        getActiveTokens: jest.fn(() => [{ document: { disposition } }]),
      };
    }

    function makeMarkedTargetActor({ flag = null } = {}) {
      const target = makeActor('common');
      target.getFlag = jest.fn((scope, key) => (key == 'techSpecsMarked' ? flag : undefined));
      return target;
    }

    beforeEach(() => {
      game.combat = { id: 'combat1', round: 2 };
    });

    afterEach(() => {
      game.combat = null;
    });

    test("grants +1 shiftUp on a melee OR ranged attack against a marked target, shared by disposition", () => {
      const target = makeMarkedTargetActor({ flag: { combatId: 'combat1', round: 2, disposition: 1 } });
      game.user.targets.first.mockReturnValue({ actor: target });
      const actor = makeAttackerActor({ disposition: 1 });

      expect(dice._getAutomaticCombatModifiers(actor, meleeWeaponEffect)).toEqual({
        ...defaultModifiers, shiftUp: 1,
        sources: [{ id: 'techSpecs', label: 'Tech Specs', shiftUp: 1, shiftDown: 0, edge: false, snag: false }],
      });
      // Ranged (not melee-only, unlike Team Focus) - only the shiftUp itself is asserted here, since
      // the shared rangedWeaponEffect fixture also triggers an unrelated pre-existing Reach downshift.
      expect(dice._getAutomaticCombatModifiers(actor, rangedWeaponEffect).shiftUp).toBe(1);
    });

    test("still applies the round after the mark", () => {
      const target = makeMarkedTargetActor({ flag: { combatId: 'combat1', round: 1, disposition: 1 } });
      game.user.targets.first.mockReturnValue({ actor: target });
      const actor = makeAttackerActor({ disposition: 1 });

      expect(dice._getAutomaticCombatModifiers(actor, meleeWeaponEffect).shiftUp).toBe(1);
    });

    test("doesn't apply for an opposing-disposition attacker, an expired mark, or no mark at all", () => {
      const enemyActor = makeAttackerActor({ disposition: -1 });
      const target = makeMarkedTargetActor({ flag: { combatId: 'combat1', round: 2, disposition: 1 } });
      game.user.targets.first.mockReturnValue({ actor: target });
      expect(dice._getAutomaticCombatModifiers(enemyActor, meleeWeaponEffect)).toEqual(defaultModifiers);

      const actor = makeAttackerActor({ disposition: 1 });
      const staleTarget = makeMarkedTargetActor({ flag: { combatId: 'combat1', round: 0, disposition: 1 } });
      game.user.targets.first.mockReturnValue({ actor: staleTarget });
      expect(dice._getAutomaticCombatModifiers(actor, meleeWeaponEffect)).toEqual(defaultModifiers);

      const unmarkedTarget = makeMarkedTargetActor();
      game.user.targets.first.mockReturnValue({ actor: unmarkedTarget });
      expect(dice._getAutomaticCombatModifiers(actor, meleeWeaponEffect)).toEqual(defaultModifiers);
    });

    describe("Technical Mastery's own Edge widening (20th level)", () => {
      const TECHNICAL_MASTERY_ID = "Compendium.essence20.quartermasters_guide_to_gear.Item.QKlXoVgNMq7Kv58L";

      let originalActors;
      beforeEach(() => {
        originalActors = global.game.actors;
      });
      afterEach(() => {
        global.game.actors = originalActors;
      });

      test("also grants Edge when the original caster holds Technical Mastery", () => {
        const target = makeMarkedTargetActor({
          flag: { combatId: 'combat1', round: 2, disposition: 1, casterId: 'caster1' },
        });
        game.user.targets.first.mockReturnValue({ actor: target });
        global.game.actors = {
          get: jest.fn(() => ({ items: [{ type: 'perk', flags: { core: { sourceId: TECHNICAL_MASTERY_ID } } }] })),
        };
        const actor = makeAttackerActor({ disposition: 1 });

        const result = dice._getAutomaticCombatModifiers(actor, meleeWeaponEffect);

        expect(result.shiftUp).toBe(1);
        expect(result.edge).toBe(true);
      });

      test("doesn't grant Edge when the caster lacks Technical Mastery", () => {
        const target = makeMarkedTargetActor({
          flag: { combatId: 'combat1', round: 2, disposition: 1, casterId: 'caster1' },
        });
        game.user.targets.first.mockReturnValue({ actor: target });
        global.game.actors = { get: jest.fn(() => ({ items: [] })) };
        const actor = makeAttackerActor({ disposition: 1 });

        const result = dice._getAutomaticCombatModifiers(actor, meleeWeaponEffect);

        expect(result.shiftUp).toBe(1);
        expect(result.edge).toBe(false);
      });
    });
  });

  describe("Rifle Tally (Quartermaster's Guide to Gear, Strafer Focus, Vanguard, 20th level, p.28)", () => {
    const RIFLE_TALLY_ID = "Compendium.essence20.quartermasters_guide_to_gear.Item.dXCi2IGJnV47wzqe";

    function makeRifleTallyActor({ hasPerk = true } = {}) {
      const items = hasPerk ? [{ type: 'perk', flags: { core: { sourceId: RIFLE_TALLY_ID } } }] : [];
      items.get = jest.fn(() => null);
      return { ...makeActor('common'), id: 'gunner1', items };
    }

    function makeGroundTargetActor() {
      const target = makeActor('common');
      target.system.movement = { aerial: { base: 0 } };
      return target;
    }

    function makeAerialTargetActor() {
      const target = makeActor('common');
      target.system.movement = { aerial: { base: 30 } };
      return target;
    }

    let originalActors;
    beforeEach(() => {
      originalActors = global.game.actors;
    });
    afterEach(() => {
      global.game.actors = originalActors;
    });

    function stubAirVehicle(riderActor, movementType = 'aerial') {
      global.game.actors = [{
        type: 'vehicle',
        system: {
          actors: { crew1: { vehicleRole: 'gunner', uuid: riderActor.uuid } },
          movement: { aerial: { base: movementType == 'aerial' ? 30 : 0 } },
        },
      }];
    }

    test("grants Edge attacking a non-aerial target from an air vehicle, with the Perk", () => {
      const actor = makeRifleTallyActor();
      actor.uuid = 'Actor.gunner1';
      stubAirVehicle(actor);
      game.user.targets.first.mockReturnValue({ actor: makeGroundTargetActor() });

      expect(dice._getAutomaticCombatModifiers(actor, meleeWeaponEffect).edge).toBe(true);
    });

    test("doesn't apply against an aerial target, without the Perk, or without riding an air vehicle", () => {
      const actor = makeRifleTallyActor();
      actor.uuid = 'Actor.gunner1';
      stubAirVehicle(actor);
      game.user.targets.first.mockReturnValue({ actor: makeAerialTargetActor() });
      expect(dice._getAutomaticCombatModifiers(actor, meleeWeaponEffect).edge).toBe(false);

      const noPerkActor = makeRifleTallyActor({ hasPerk: false });
      noPerkActor.uuid = 'Actor.gunner2';
      stubAirVehicle(noPerkActor);
      game.user.targets.first.mockReturnValue({ actor: makeGroundTargetActor() });
      expect(dice._getAutomaticCombatModifiers(noPerkActor, meleeWeaponEffect).edge).toBe(false);

      const groundedActor = makeRifleTallyActor();
      groundedActor.uuid = 'Actor.gunner3';
      stubAirVehicle(groundedActor, 'ground');
      game.user.targets.first.mockReturnValue({ actor: makeGroundTargetActor() });
      expect(dice._getAutomaticCombatModifiers(groundedActor, meleeWeaponEffect).edge).toBe(false);
    });
  });

