  describe("Takedown (GI Joe CRB, Commando base, 5th level, p.72) - outcome matrix", () => {
    const TAKEDOWN_EXPERT_ID = "Compendium.essence20.gi_joe_crb.Item.gO9IixdCX0fhReZk";

    function makeTakedownAttacker(level, { perkIds = [] } = {}) {
      return {
        getRollData: () => ({}),
        getFlag: jest.fn(() => undefined),
        unsetFlag: jest.fn(),
        items: perkIds.map(perkId => ({ type: 'perk', flags: { core: { sourceId: perkId } } })),
        system: { level },
      };
    }

    function makeTakedownTargetActor(threatLevel) {
      return {
        name: 'Enemy',
        toggleStatusEffect: jest.fn(),
        system: { stun: { value: 0 }, health: { value: 5, max: 5 }, immunities: {}, threatLevel },
      };
    }

    function makeCheckContext() {
      return {
        entries: [{ name: 'Enemy', targetUuid: 'Actor.e1', difficulty: 10, showDifficulty: true }],
        damageValue: null, damageType: null, effectName: null, alternateEffects: [],
        isTakedownAttempt: true,
      };
    }

    beforeEach(() => {
      fromUuid.mockReset();
      global.Roll = FakeRoll;
    });

    test("hit + target not above the attacker's level -> Restrained + Unconscious", async () => {
      FakeRoll.nextTotal = 20;
      const enemy = makeTakedownTargetActor(5);
      fromUuid.mockResolvedValue(enemy);

      await freshDice._rollSkillHelper('d20 + 0', makeTakedownAttacker(10), 'flavor', false, makeCheckContext(), {});

      expect(enemy.toggleStatusEffect).toHaveBeenCalledWith('restrained', { active: true });
      expect(enemy.toggleStatusEffect).toHaveBeenCalledWith('unconscious', { active: true });
      expect(enemy.toggleStatusEffect).not.toHaveBeenCalledWith('grappled', expect.anything());
    });

    test("hit + target above the attacker's level -> Grapple instead", async () => {
      FakeRoll.nextTotal = 20;
      const enemy = makeTakedownTargetActor(15);
      fromUuid.mockResolvedValue(enemy);

      await freshDice._rollSkillHelper('d20 + 0', makeTakedownAttacker(10), 'flavor', false, makeCheckContext(), {});

      expect(enemy.toggleStatusEffect).toHaveBeenCalledWith('grappled', { active: true });
      expect(enemy.toggleStatusEffect).not.toHaveBeenCalledWith('restrained', expect.anything());
    });

    test("miss + target not above the attacker's level -> Grapple instead", async () => {
      FakeRoll.nextTotal = 5; // below difficulty 10 - a miss
      const enemy = makeTakedownTargetActor(5);
      fromUuid.mockResolvedValue(enemy);

      await freshDice._rollSkillHelper('d20 + 0', makeTakedownAttacker(10), 'flavor', false, makeCheckContext(), {});

      expect(enemy.toggleStatusEffect).toHaveBeenCalledWith('grappled', { active: true });
    });

    test("miss + target above the attacker's level -> no effect at all", async () => {
      FakeRoll.nextTotal = 5; // below difficulty 10 - a miss
      const enemy = makeTakedownTargetActor(15);
      fromUuid.mockResolvedValue(enemy);

      await freshDice._rollSkillHelper('d20 + 0', makeTakedownAttacker(10), 'flavor', false, makeCheckContext(), {});

      expect(enemy.toggleStatusEffect).not.toHaveBeenCalled();
    });

    test("Takedown Expert also Immobilizes on a miss + not-outmatched Grapple", async () => {
      FakeRoll.nextTotal = 5; // below difficulty 10 - a miss
      const enemy = makeTakedownTargetActor(5);
      fromUuid.mockResolvedValue(enemy);
      const attacker = makeTakedownAttacker(10, { perkIds: [TAKEDOWN_EXPERT_ID] });

      await freshDice._rollSkillHelper('d20 + 0', attacker, 'flavor', false, makeCheckContext(), {});

      expect(enemy.toggleStatusEffect).toHaveBeenCalledWith('grappled', { active: true });
      expect(enemy.toggleStatusEffect).toHaveBeenCalledWith('immobilized', { active: true });
    });

    test("Takedown Expert doesn't Immobilize on a hit + outmatched Grapple", async () => {
      FakeRoll.nextTotal = 20;
      const enemy = makeTakedownTargetActor(15);
      fromUuid.mockResolvedValue(enemy);
      const attacker = makeTakedownAttacker(10, { perkIds: [TAKEDOWN_EXPERT_ID] });

      await freshDice._rollSkillHelper('d20 + 0', attacker, 'flavor', false, makeCheckContext(), {});

      expect(enemy.toggleStatusEffect).toHaveBeenCalledWith('grappled', { active: true });
      expect(enemy.toggleStatusEffect).not.toHaveBeenCalledWith('immobilized', expect.anything());
    });

    test("doesn't apply anything without the attempt flagged", async () => {
      FakeRoll.nextTotal = 20;
      const enemy = makeTakedownTargetActor(5);
      fromUuid.mockResolvedValue(enemy);
      const checkContext = { ...makeCheckContext(), isTakedownAttempt: false };

      await freshDice._rollSkillHelper('d20 + 0', makeTakedownAttacker(10), 'flavor', false, checkContext, {});

      expect(enemy.toggleStatusEffect).not.toHaveBeenCalled();
    });
  });

