  describe("Hup! Hup! Hup! Hup! Hup! (Sgt Slaughter Sourcebook, Drill Instructor Focus, Officer, 6th level, p.10) - post-hit broadcast", () => {
    function makeAllyToken() {
      const flagStore = {};
      const actorObj = {
        getFlag: jest.fn((scope, key) => flagStore[key]),
        setFlag: jest.fn(async (scope, key, value) => { flagStore[key] = value; }),
      };
      return { actor: actorObj, document: { disposition: 1 }, center: { x: 0, y: 0 } };
    }

    const hupCheckContext = {
      entries: [{ name: 'Officer', targetUuid: null, difficulty: 0, showDifficulty: true }],
      damageValue: 0, damageType: null, effectName: null, alternateEffects: [],
      isHupHupHupHupHupAttempt: true,
    };

    afterEach(() => {
      global.canvas.tokens.placeables = [];
    });

    test("broadcasts the rounded-down total to every nearby ally", async () => {
      global.Roll = FakeRoll;
      FakeRoll.nextTotal = 24; // rounds down to 20
      const selfToken = { document: { disposition: 1 }, center: { x: 0, y: 0 } };
      const officer = { getRollData: () => ({}), getActiveTokens: jest.fn(() => [selfToken]) };
      const ally = makeAllyToken();
      global.canvas.tokens.placeables = [selfToken, ally];

      await freshDice._rollSkillHelper('d20 + 0', officer, 'flavor', false, hupCheckContext, {});

      expect(ally.actor.setFlag).toHaveBeenCalledWith(
        'essence20', 'pendingHupHupHupHupHupBonus', expect.objectContaining({ bonus: 20 }),
      );
    });

    test("doesn't broadcast anything without the attempt flagged", async () => {
      global.Roll = FakeRoll;
      FakeRoll.nextTotal = 24;
      const selfToken = { document: { disposition: 1 }, center: { x: 0, y: 0 } };
      const officer = { getRollData: () => ({}), getActiveTokens: jest.fn(() => [selfToken]) };
      const ally = makeAllyToken();
      global.canvas.tokens.placeables = [selfToken, ally];

      await freshDice._rollSkillHelper(
        'd20 + 0', officer, 'flavor', false, { ...hupCheckContext, isHupHupHupHupHupAttempt: false }, {},
      );

      expect(ally.actor.setFlag).not.toHaveBeenCalled();
    });
  });

