  describe("Powerful Suggestions (Enigma of Combination, Counselor Focus, 17th level, p.34) - consumption", () => {
    function makeSuggestionActor(suggestion) {
      const flags = { pendingPowerfulSuggestion: suggestion };
      return {
        getRollData: () => ({}),
        getFlag: jest.fn((scope, key) => flags[key]),
        unsetFlag: jest.fn(async (scope, key) => {
          delete flags[key];
        }),
        _flags: flags,
      };
    }

    const suggestionContext = {
      entries: [{ name: 'Actor', targetUuid: null, difficulty: 8, showDifficulty: true }],
      damageValue: null, damageType: null, effectName: null, alternateEffects: [],
    };

    function lastRenderedResults() {
      const renderCall = global.foundry.applications.handlebars.renderTemplate.mock.calls.slice(-1)[0];
      return renderCall[1].results;
    }

    test("'excel': a marginal Success (multiplier 1) becomes a Critical Success and clears the flag", async () => {
      global.Roll = FakeRoll;
      FakeRoll.nextTotal = 10; // floor(10/8) = 1, a marginal success
      const actor = makeSuggestionActor({ skill: 'athletics', effect: 'excel' });

      await freshDice._rollSkillHelper('d20 + 0', actor, 'flavor', false, suggestionContext, { skill: 'athletics' });

      expect(lastRenderedResults()[0].multiplier).toBe(2);
      expect(actor.unsetFlag).toHaveBeenCalledWith('essence20', 'pendingPowerfulSuggestion');
    });

    test("'fail': achieving a genuine Critical Success (multiplier >= 2) proves it wrong and clears the flag", async () => {
      global.Roll = FakeRoll;
      FakeRoll.nextTotal = 20; // floor(20/8) = 2, already a Critical Success
      const actor = makeSuggestionActor({ skill: 'athletics', effect: 'fail' });

      await freshDice._rollSkillHelper('d20 + 0', actor, 'flavor', false, suggestionContext, { skill: 'athletics' });

      expect(lastRenderedResults()[0].multiplier).toBe(2);
      expect(actor.unsetFlag).toHaveBeenCalledWith('essence20', 'pendingPowerfulSuggestion');
    });

    test("'fail': stays banked while only a marginal Success is achieved", async () => {
      global.Roll = FakeRoll;
      FakeRoll.nextTotal = 10; // floor(10/8) = 1, not yet a Critical Success
      const actor = makeSuggestionActor({ skill: 'athletics', effect: 'fail' });

      await freshDice._rollSkillHelper('d20 + 0', actor, 'flavor', false, suggestionContext, { skill: 'athletics' });

      expect(lastRenderedResults()[0].multiplier).toBe(1);
      expect(actor.unsetFlag).not.toHaveBeenCalled();
    });

    test("doesn't apply for a different Skill", async () => {
      global.Roll = FakeRoll;
      FakeRoll.nextTotal = 10;
      const actor = makeSuggestionActor({ skill: 'stealth', effect: 'excel' });

      await freshDice._rollSkillHelper('d20 + 0', actor, 'flavor', false, suggestionContext, { skill: 'athletics' });

      expect(lastRenderedResults()[0].multiplier).toBe(1);
      expect(actor.unsetFlag).not.toHaveBeenCalled();
    });
  });

